Object.assign(PLAN_TXT.de.notes,{"classic3b": ["Schlendere durch den Park, wenn das Abendpublikum kommt.", "Ein Negroni im hundertjährigen Café, heute eine berühmte Bar.", "Handgemachte Pasta in einer legendären Trattoria. Unbedingt reservieren.", "Dessert am Kamin, an den meisten Abenden mit Live-Jazz."], "classic3c": ["Starte am Geburtsort der modernen LGBTQ+-Bewegung, heute ein Nationaldenkmal.", "Paella und Sangria in einem spanischen Lokal, das seit 1941 besteht.", "Ein winziger Kellerclub mit Jazz bis in die frühen Morgenstunden."], "classic6b": ["Starte am Arch und am Brunnen.", "Saisonale italienische Gerichte in einem hellen Raum.", "Der Uhrturm der Jefferson Market Library, dann die Läden der Bleecker Street.", "Eine Kaffeepause an einer ruhigen Ecke im West Village.", "Steak frites in einer Brasserie im Pariser Stil.", "Late-Night-Jazz in einem Kellerclub, nur ein paar Schritte entfernt."], "classic6c": ["Schau den Schachspielern und Straßenmusikern zu.", "Ein schneller Espresso in einem kleinen Lieblingsort der Nachbarschaft.", "Spaziere westwärts zum Hudson River mit weitem Blick.", "Japanische Highballs in einer verspielten Bar an der Hudson Street.", "Abendessen in einer intimen italienischen Osteria an der Sixth Avenue.", "Ein Indie-Film im beliebten Programmkino des Village."], "date3b": ["Eine gemütliche Runde durch den beleuchteten Park.", "Schallplatten und ein wunderschön gemixter Cocktail.", "Eine intime Sushi-Theke, nach Wahl des Küchenchefs. Unbedingt reservieren.", "Gewürzbetonte Cocktails ein paar Türen weiter."], "date3c": ["Starte unter dem Arch, wenn sich der Himmel rosa färbt.", "Ein sonniges, von der Provence inspiriertes Bistro direkt am Park.", "Zum Abschluss französischer Wein und kleine Gerichte gleich nebenan."], "date6b": ["Starte auf dem Kopfsteinpflaster der Washington Mews.", "Kaffee von einer beliebten New Yorker Rösterei.", "Spaziere westwärts nach Little Island, einem Park, der über dem Hudson schwebt.", "Spritz in einer kleinen italienischen Schmuckkästchen-Bar.", "Prime Rib in einem dunklen, intimen Raum. Lange im Voraus reservieren.", "Zum Abschluss ein Glas in einer rustikalen italienischen Weinbar."], "date6c": ["Spaziere über den Hochpark über dem Meatpacking District.", "Highballs in einer verspielten japanisch-amerikanischen Bar.", "Ein kerzenbeleuchteter West-Village-Klassiker mit Gartenraum.", "Intimer Piano-Jazz in einem gemütlichen Kellerraum.", "Ein letzter Cocktail in einem Speakeasy mit Live-Jazz."], "laughs3b": ["Kräftige malaysische Aromen zum Start in den Abend.", "Stand-up in einem intimen Kellerclub an der MacDougal Street. Unbedingt reservieren.", "Jazz bis in die frühen Morgenstunden."], "laughs3c": ["Mezcal und mexikanische Gerichte zum Auftakt.", "Eine stilvolle Cocktailbar in der Nachbarschaft.", "Einfallsreiche Cocktails von einem weltbekannten Team, gleich nebenan.", "Noch eine Runde, mit Platten auf dem Plattenteller."], "laughs6b": ["Starte am Stonewall, einem Nationaldenkmal und Wahrzeichen des Village.", "Highballs zur Happy Hour an der Hudson Street.", "Peruanisches Grillhähnchen, Ceviche und Pisco.", "Stand-up in einem intimen Club an der MacDougal Street. Unbedingt reservieren.", "Später Jazz in einem winzigen Kellerclub."], "laughs6c": ["Die Jefferson Market Library, dann die Bleecker Street hinunter.", "Sonnenuntergang über dem Hudson vom Pier aus.", "Paella und ein Krug Sangria, Tradition seit 1941.", "New Yorks berühmter Comedy-Club, in dem große Namen spontan auftreten. Unbedingt reservieren.", "Späte Cocktails in einer legendären Bar mit Küche bis spät."]});
