Object.assign(PLAN_TXT.zh.notes,{"classic3b": ["趁傍晚人潮渐多时在公园里漫步。", "在百年咖啡馆变身的名酒吧来一杯内格罗尼。", "在地标意式餐馆品尝手工意面。请提前预订。", "在壁炉旁享用甜点，几乎每晚都有现场爵士乐。"], "classic3c": ["从现代 LGBTQ+ 平权运动的发源地出发，这里如今是国家纪念地。", "在 1941 年开业的西班牙餐厅享用海鲜饭和桑格利亚。", "小小的地下爵士俱乐部，演出持续到凌晨。"], "classic6b": ["从拱门和喷泉出发。", "在明亮通透的餐厅享用应季意式小盘菜。", "先看杰斐逊市场图书馆的钟楼，再逛布利克街的小店。", "在西村安静的街角来杯咖啡歇歇脚。", "在巴黎风格小酒馆餐厅享用牛排薯条。", "几步之遥的地下俱乐部，深夜爵士乐。"], "classic6c": ["看看下棋的人和街头音乐人。", "在当地人喜爱的小店来一杯浓缩咖啡。", "向西走到哈德逊河边，视野开阔。", "在哈德逊街一家有趣的酒吧喝日式嗨棒。", "在第六大道的温馨意式小馆享用晚餐。", "在格林威治村备受喜爱的艺术影院看一部独立电影。"], "date3b": ["在灯光下慢慢绕公园走一圈。", "黑胶唱片配一杯精心调制的鸡尾酒。", "私密的寿司吧台，主厨精选。请提前预订。", "走几步，再来一杯以香料为灵感的鸡尾酒。"], "date3c": ["在天空染成粉色时，从拱门下出发。", "紧邻公园、阳光明媚的普罗旺斯风小酒馆。", "最后去隔壁，以法国葡萄酒和小盘菜收尾。"], "date6b": ["从华盛顿马厩街的鹅卵石路出发。", "来一杯纽约人钟爱的烘焙咖啡。", "向西走到小岛公园，一座漂浮在哈德逊河上的公园。", "在珠宝盒般的意式小酒吧喝 Spritz。", "在昏暗私密的餐厅享用肋眼牛排。请尽早预订。", "最后在质朴的意式葡萄酒吧喝一杯。"], "date6c": ["漫步肉库区上方的高架公园。", "在有趣的日美风格酒吧喝嗨棒。", "烛光摇曳、设有花园厅的西村经典餐厅。", "在温馨的地下小厅欣赏私密的钢琴爵士。", "在有现场爵士乐的地下酒吧喝最后一杯。"], "laughs3b": ["以浓郁的马来西亚风味开启夜晚。", "在麦克杜格尔街的私密地下俱乐部看脱口秀。请提前预订。", "深夜爵士，直到凌晨。"], "laughs3c": ["先来梅斯卡尔和墨西哥菜。", "一家时髦的街坊鸡尾酒吧。", "隔壁就是世界知名团队的创意鸡尾酒。", "再来一轮，伴着黑胶唱片。"], "laughs6b": ["从石墙出发，这里是国家纪念地，也是格林威治村的标志。", "在哈德逊街享受欢乐时光的嗨棒。", "秘鲁烤鸡、酸橘汁腌鱼和皮斯科酒。", "在麦克杜格尔街的私密俱乐部看脱口秀。请提前预订。", "在小小的地下俱乐部听深夜爵士。"], "laughs6c": ["先看杰斐逊市场图书馆，再沿布利克街一路走。", "在码头看哈德逊河上的日落。", "海鲜饭配一壶桑格利亚，自 1941 年延续至今的传统。", "纽约著名的喜剧俱乐部，常有大牌明星突然登场。请提前预订。", "在厨房营业到深夜的传奇酒吧喝几杯。"]});
